import { gateResult } from "@bendyline/gezel-sdk/checks";
import fs from "fs";

const reportPath = "out/inventory-report.json";

try {
  const data = JSON.parse(fs.readFileSync(reportPath, "utf8"));

  // Validation logic: Ensure keys exist and are populated
  const requiredKeys = ["totals", "out_of_stock", "impossible_quantities", "low_stock"];
  const isValid = requiredKeys.every(key => data.hasOwnProperty(key));

  if (isValid) {
    gezel.output(gateResult("success"));
  } else {
    gezel.output(gateResult("failure", "Missing required keys in report."));
  }
} catch (e) {
  gezel.output(gateResult("failure", `Failed to parse report: ${e.message}`));
}

