    report.totals.total_quantity += item.qty;

    if (item.qty === 0) {
      report.out_of_stock.push(item);
    } else if (item.qty < 0) {
      report.impossible_quantities.push(item);
    }

    if (item.qty < 10 && item.qty >= 0) {
      report.low_stock.push(item);
    }
  });

  fs.writeFileSync(outputPath, JSON.stringify(report, null, 2));
  console.log(`Report generated successfully at ${outputPath}`);
} catch (err) {
  console.error('Error processing inventory:', err);
  process.exit(1);
}


